ow new Error("unresolved:" + "quotationInfo.tddLwprc"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dlt_quotationList.getCellData(0, "tddLwprc") ?? (() => { throw new Error("unresolved:" + "quotationInfo.tddLwprc"); })())) == null ? '' : ((dlt_quotationList.getCellData(0, "tddLwprc") ?? (() => { throw new Error("unresolved:" + "quotationInfo.tddLwprc"); })())))),"date":(String(((dlt_quotationList.getCellData(0, "trdDd") ?? (() => { throw new Error("unresolved:" + "quotationInfo.trdDd"); })())) == null ? '' : ((dlt_quotationList.getCellData(0, "trdDd") ?? (() => { throw new Error("unresolved:" + "quotationInfo.trdDd"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dlt_quotationList.getCellData(0, "trdDd") ?? (() => { throw new Error("unresolved:" + "quotationInfo.trdDd"); })())) == null ? '' : ((dlt_quotationList.getCellData(0, "trdDd") ?? (() => { throw new Error("unresolved:" + "quotationInfo.trdDd"); })())))),"close":(String(((dlt_quotationList.getCellData(0, "tddClsprc") ?? (() => { throw new Error("unresolved:" + "quotationInfo.tddClsprc"); })())) == null ? '' : ((dlt_quotationList.getCellData(0, "tddClsprc") ?? (() => { throw new Error("unresolved:" + "quotationInfo.tddClsprc"); })()))).indexOf('$' + '{') >= 0 ? '' : String(((dlt_quotationList.getCellData(0, "tddClsprc") ?? (() => { throw new Error("unresolved:" + "quotationInfo.tddClsprc"); })())) == null ? '' : ((dlt_quotationList.getCellData(0, "tddClsprc") ?? (() => { throw new Error("unresolved:" + "quotationInfo.tddClsprc"); })()))))},

