///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_Search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/company/companyinfo.do",
        ref: "dma_SearchReq",
        target: "dlt_quotationList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil20400.tx_fn_Search" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.grd_quotationList_fmt_fluc
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData r c
 * @returns
 * @hidden N
*/
scwin.grd_quotationList_fmt_fluc = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_quotationList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "flucTpCd") ?? '') : '');
        if (v === '1') { return "▲"; }
        if (v === '2') { return "▼"; }
        if (v === '4') { return "↑"; }
        if (v === '5') { return "↓"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_quotationList.fluc" }); return String(data ?? ''); }
};

/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.quotationForm || { elements: [] });
    if ($c.util.getComponent('cal_sdate').getValue()> $c.util.getComponent('cal_edate').getValue()) {
        await $c.win.alert('시작일이 종료일보다 이후 일자 입니다.');
        return;
    }
    $c.util.getComponent('dma_SearchReq').set('method', 'searchQuotation');
    frm.action = 'companyinfo.do';
    await scwin.tx_fn_Search();
    /* sdd-asis-lifecycle:end */
};


