*/
scwin.fnChartReadyHandlerDisclsAnalysisChart = function (id) {
    /* sdd-asis-lifecycle:begin fnChartReadyHandlerDisclsAnalysisChart — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent(id).setLayoutURL(scwin.layoutDisclsAnalysisChart);
    $c.util.getComponent(id).setData(scwin.dataDisclsAnalysisChart);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnDataTipFunc
 * @author Inswave
 * @date 2026. 09. 29
 * @param seriesId seriesName index xName yName data values
 * @returns
 * @hidden N
*/
scwin.fnDataTipFunc = function (seriesId, seriesName, index, xName, yName, data, values) {
    /* sdd-asis-lifecycle:begin fnDataTipFunc — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (data.gongsi) {
        scwin.fnSetGongsiData(data);
    } else {
        scwin.fnSetNoActiveFromDisclsView();
    }
    return "[" + data.date + "]<br>시 : " + data.open.format() + "<br>고 : " + data.high.format() + "<br>저 : " + data.low.format() + "<br>종 : " + data.close.format() + "<br>거 : " + data.admnt.format();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSetGongsiData
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.fnSetGongsiData = function (data) {
    /* sdd-asis-lifecycle:begin fnSetGongsiData — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (typeof data === "object") {
        scwin.fnSetNoActiveFromDisclsView();
        const varObj = $(document).find("tbody[id=disclsView]");
        varObj.find("tr[id=disclsDate-" + data.date + "]").each(function() {
                if ($(this).hasClass("first")) {
                    $(this).removeClass("first");
                    $(this).addClass("active");
                }
                console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
        });
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSetNoActiveFromDisclsView
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSetNoActiveFromDisclsView = function () {
    /* sdd-asis-lifecycle:begin fnSetNoActiveFromDisclsView — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const varObj = $(document).find("tbody[id=disclsView]");
    varObj/* 수동 전환 필요: 행 순회(find(tr)) — 컨테이너·목록을 못 정함 · to-be 에 돌 요소가 없다 */ .find("tr").each(function() {
            if ($(this).hasClass("active")) {
                $(this).removeClass("active");
                $(this).addClass("first");
            }
    });
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnMaxLabelFunc
 * @author Inswave
 * @date 2026. 09. 29
 * @param seriesId index data values
 * @returns
 * @hidden N
*/
scwin.fnMaxLabelFunc = function (seriesId, index, data, values) {
    /* sdd-asis-lifecycle:begin fnMaxLabelFunc — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const max = scwin.fnGetTypeNum(values.slice(1, values.length));
    return "<font color='#ff0000'>최고 : <b>" + max[2].format() + "</b> (" + values[0] + ")</font>";
    /* sdd-asis-lifecycle:end */
};


